// ENG-930: Obsidian node tag colours use Roam's getPleasingColors.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const EXPECTED = JSON.parse(
  readFileSync(join(dirname(fileURLToPath(import.meta.url)), "expected.json"), "utf8"),
);
const rgb = (hex) => {
  const h = hex.replace("#", "");
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
  return `rgb(${r}, ${g}, ${b})`;
};
const expectFor = (hex) => {
  const key = Object.keys(EXPECTED).find((k) => k.toLowerCase() === hex.toLowerCase());
  return { bg: rgb(EXPECTED[key].bg), fg: rgb(EXPECTED[key].fg), base: rgb(hex) };
};

const NOTE = "tag-colors.md";
const BODY = "#que-candidate What is a question?\n\n#clm-candidate A claim here\n\n#evd-candidate Some evidence\n";
const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;

const plugin = (vault) => `app.plugins.plugins[${JSON.stringify(vault.pluginId)}]`;

const nodeTypes = ({ client, vault }) =>
  client.evaluate(`return ${plugin(vault)}.settings.nodeTypes.map((n) => ({ id: n.id, name: n.name, color: n.color }));`);

const setTheme = ({ client, json }, theme) =>
  client.evaluate(`app.changeTheme(${json(theme)}); return true;`);
const getTheme = ({ client }) => client.evaluate(`return app.vault.getConfig("theme") || "moonstone";`);

const openNote = async (ctx) => {
  const { client, json } = ctx;
  const p = await ctx.writeNote(NOTE, BODY);
  await client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    leaf.view.editor.setCursor({ line: 5, ch: 0 });
    return true;
  })();`);
  await client.waitFor(`document.querySelectorAll(".workspace-leaf.mod-active .dg-discourse-tag").length >= 3`, {
    label: "three discourse tag chips",
  });
};

const readTags = ({ client }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(".workspace-leaf.mod-active .dg-discourse-tag")).map((el) => ({
    id: el.getAttribute("data-dg-discourse-tag-node"),
    fg: getComputedStyle(el).color,
    bg: getComputedStyle(el, "::before").backgroundColor,
    border: getComputedStyle(el.closest(".cm-hashtag")).borderTopWidth,
  }));`);

const compareTags = (tags, types, colorOverride = {}) => {
  const mismatches = [];
  for (const t of tags) {
    const type = types.find((n) => n.id === t.id);
    const exp = expectFor(colorOverride[t.id] ?? type.color);
    if (t.bg !== exp.bg || t.fg !== exp.fg) mismatches.push(`${type.name}: got ${t.bg}/${t.fg}, want ${exp.bg}/${exp.fg}`);
  }
  return mismatches;
};

const tagScenario = ({ name, theme }) => ({
  name,
  input: `theme=${theme}; open note with #que/#clm/#evd-candidate tags`,
  expected: "each chip's ::before bg and text colour equal getPleasingColors(node colour); no border",
  setup: async (ctx) => {
    const saved = await getTheme(ctx);
    await setTheme(ctx, theme);
    return { saved };
  },
  run: async (ctx) => {
    await openNote(ctx);
    return { tags: await readTags(ctx), types: await nodeTypes(ctx) };
  },
  expect: ({ tags, types }) => {
    const mismatches = compareTags(tags, types);
    const borders = tags.filter((t) => t.border !== "0px");
    return {
      pass: tags.length >= 3 && mismatches.length === 0 && borders.length === 0,
      actual: mismatches.length || borders.length
        ? [...mismatches, ...borders.map((b) => `border ${b.border}`)].join("; ")
        : tags.map((t) => `${types.find((n) => n.id === t.id).name} ${t.bg}/${t.fg}`).join(", "),
    };
  },
  teardown: async (ctx, { saved }) => setTheme(ctx, saved),
});

const defaultColorScenario = {
  name: "Default colour tag (Question colour cleared)",
  input: "clear Question's colour in memory; refresh tag colours",
  expected: "Question chip uses getPleasingColors(#1d1d1d), the palette default for index 0 (same as Roam)",
  setup: async (ctx) => {
    const { client, vault } = ctx;
    const saved = await client.evaluate(`const n = ${plugin(vault)}.settings.nodeTypes[0]; const c = n.color; n.color = ""; app.workspace.updateOptions(); return { id: n.id, color: c };`);
    return { saved };
  },
  run: async (ctx, { saved }) => {
    await openNote(ctx);
    await ctx.client.waitFor(`(() => { const el = document.querySelector('.workspace-leaf.mod-active .dg-discourse-tag[data-dg-discourse-tag-node="${saved.id}"]'); return !!el && getComputedStyle(el, "::before").backgroundColor === "${expectFor("#1d1d1d").bg}"; })() === true`, { label: "default colour applied" }).catch(() => {});
    return { tags: await readTags(ctx), types: await nodeTypes(ctx), id: saved.id };
  },
  expect: ({ tags, types, id }) => {
    const q = tags.filter((t) => t.id === id);
    const mismatches = compareTags(q, types, { [id]: "#1d1d1d" });
    return { pass: q.length === 1 && mismatches.length === 0, actual: mismatches.join("; ") || `Question ${q[0]?.bg}/${q[0]?.fg}` };
  },
  teardown: async ({ client, vault, json }, { saved }) =>
    client.evaluate(`const n = ${plugin(vault)}.settings.nodeTypes.find((x) => x.id === ${json(saved.id)}); n.color = ${json(saved.color)}; app.workspace.updateOptions(); return true;`),
};

const searchScenario = ({ name, theme }) => ({
  name,
  input: `theme=${theme}; open node search; filter by Claim + Evidence; type "a"`,
  expected: "type chips and filled result badges use pleasing bg/text; candidate outline and filter dots use the solid node colour",
  setup: async (ctx) => {
    const saved = await getTheme(ctx);
    await setTheme(ctx, theme);
    return { saved };
  },
  run: async (ctx) => {
    const { client, json, vault } = ctx;
    const types = await nodeTypes(ctx);
    await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
    await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input" });
    await client.evaluate(`document.querySelector('${MODAL} button[aria-label^="Filter by type"]').click(); return true;`);
    await client.waitFor(`document.querySelectorAll('${MODAL} input[type=checkbox]').length >= 4`, { label: "filter panel" });
    const dots = await client.evaluate(`return Array.from(document.querySelectorAll('${MODAL} label')).map((l) => ({
      name: l.textContent.trim(), dot: l.querySelector("span.rounded-full") && getComputedStyle(l.querySelector("span.rounded-full")).backgroundColor,
    })).filter((d) => d.dot);`);
    for (const target of ["Claim", "Evidence"]) {
      await client.evaluate(`const l = Array.from(document.querySelectorAll('${MODAL} label')).find((x) => x.textContent.trim() === ${json(target)}); l.querySelector("input").click(); return true;`);
    }
    await ctx.screenshot?.("filter-open");
    await client.evaluate(`document.querySelector('${MODAL} button[aria-label^="Filter by type"]').click(); document.querySelector(${json(INPUT)}).focus(); return true;`);
    await client.typeText("a");
    await new Promise((r) => setTimeout(r, 800));
    const chips = await client.evaluate(`return Array.from(document.querySelectorAll('${MODAL} span[role=button][aria-label]')).map((c) => ({
