+  id: "claim",
+  name: "Claim",
+  format: "CLM - {content}",
+  color,
+  created: 0,
+  modified: 0,
+});
+
+const pleasing = (hex: string) => {
+  const { background, text } = getPleasingColors(colord(hex));
+  return { baseColor: hex, backgroundColor: background, textColor: text };
